import{_ as p,a0 as l,w as d,s as r,ao as o,I as i,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Linux 上為你的任務創建一個自定義的系統托盤指示器 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上為你的任務創建一個自定義的系統托盤指示器 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上為你的任務創建一個自定義的系統托盤指示器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上為你的任務創建一個自定義的系統托盤指示器 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190302 Create a Custom System Tray Indicator For Your Tasks on Linux","title":"在 Linux 上為你的任務創建一個自定義的系統托盤指示器","tag":"201907","desc":""},"relativePath":"201907/20190302 Create a Custom System Tray Indicator For Your Tasks on Linux.md","filePath":"[post].md"}'),c={name:"201907/20190302 Create a Custom System Tray Indicator For Your Tasks on Linux.md"};function u(m,s,h,g,k,y){const n=l("Link");return d(),r("div",null,[s[18]||(s[18]=o('<h1 id="在-linux-上為你的任務創建一個自定義的系統托盤指示器" tabindex="-1">在 Linux 上為你的任務創建一個自定義的系統托盤指示器 <a class="header-anchor" href="#在-linux-上為你的任務創建一個自定義的系統托盤指示器" aria-label="Permalink to “在 Linux 上為你的任務創建一個自定義的系統托盤指示器”">​</a></h1><p>系統托盤圖標如今仍是一個很神奇的功能。只需要右擊圖標，然後選擇想要的動作，你就可以大幅簡化你的生活並且減少日常行為中的大量無用的點擊。</p><p>一説到有用的系統托盤圖標，我們很容易就想到 Skype、Dropbox 和 VLC：</p><p><img src="https://i2.wp.com/fosspost.org/wp-content/uploads/2019/02/Screenshot-at-2019-02-28-0808.png?resize=407%2C345&amp;ssl=1" alt="Create a Custom System Tray Indicator For Your Tasks on Linux" title="Create a Custom System Tray Indicator For Your Tasks on Linux 12"></p><p>然而系統托盤圖標實際上要更有用得多；你可以根據自己的需求創建自己的系統托盤圖標。本指導將會教你通過簡單的幾個步驟來實現這一目的。</p><h3 id="前置條件" tabindex="-1">前置條件 <a class="header-anchor" href="#前置條件" aria-label="Permalink to “前置條件”">​</a></h3><p>我們將要用 Python 來實現一個自定義的系統托盤指示器。Python 可能已經默安裝在所有主流的 Linux 發行版中了，因此你只需要確定一下它已經被安裝好了（此處使用版本為 2.7）。另外，我們還需要安裝好 <code>gir1.2-appindicator3</code> 包。該庫能夠讓我們很容易就能創建系統圖標指示器。</p><p>在 Ubuntu/Mint/Debian 上安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install gir1.2-appindicator3</span></span></code></pre></div><p>在 Fedora 上安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install libappindicator-gtk3</span></span></code></pre></div><p>對於其他發行版，只需要搜索包含 “appindicator” 的包就行了。</p>',12)),i("p",null,[s[1]||(s[1]=a("在 GNOME Shell 3.26 開始，系統托盤圖標被刪除了。你需要安裝 ",-1)),e(n,{href:"https://extensions.gnome.org/extension/1031/topicons/"},{default:t(()=>[...s[0]||(s[0]=[a("這個擴展",-1)])]),_:1}),s[2]||(s[2]=a("（或者其他擴展）來為桌面啓用該功能。否則你無法看到我們創建的指示器。",-1))]),s[19]||(s[19]=o(`<h3 id="基礎代碼" tabindex="-1">基礎代碼 <a class="header-anchor" href="#基礎代碼" aria-label="Permalink to “基礎代碼”">​</a></h3><p>下面是該指示器的基礎代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/python</span></span>
<span class="line"><span>import os</span></span>
<span class="line"><span>from gi.repository import Gtk as gtk, AppIndicator3 as appindicator</span></span>
<span class="line"><span>def main():</span></span>
<span class="line"><span>  indicator = appindicator.Indicator.new(&quot;customtray&quot;, &quot;semi-starred-symbolic&quot;, appindicator.IndicatorCategory.APPLICATION_STATUS)</span></span>
<span class="line"><span>  indicator.set_status(appindicator.IndicatorStatus.ACTIVE)</span></span>
<span class="line"><span>  indicator.set_menu(menu())</span></span>
<span class="line"><span>  gtk.main()</span></span>
<span class="line"><span>def menu():</span></span>
<span class="line"><span>  menu = gtk.Menu()</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  command_one = gtk.MenuItem(&#39;My Notes&#39;)</span></span>
<span class="line"><span>  command_one.connect(&#39;activate&#39;, note)</span></span>
<span class="line"><span>  menu.append(command_one)</span></span>
<span class="line"><span>  exittray = gtk.MenuItem(&#39;Exit Tray&#39;)</span></span>
<span class="line"><span>  exittray.connect(&#39;activate&#39;, quit)</span></span>
<span class="line"><span>  menu.append(exittray)</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  menu.show_all()</span></span>
<span class="line"><span>  return menu</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>def note(_):</span></span>
<span class="line"><span>  os.system(&quot;gedit $HOME/Documents/notes.txt&quot;)</span></span>
<span class="line"><span>def quit(_):</span></span>
<span class="line"><span>  gtk.main_quit()</span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>  main()</span></span></code></pre></div><p>我們待會會解釋一下代碼是怎麼工作的。但是現在，讓我們將該文本保存為 <code>tray.py</code>，然後使用 Python 運行之：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python tray.py</span></span></code></pre></div><p>我們會看到指示器運行起來了，如下圖所示：</p><p><img src="https://i2.wp.com/fosspost.org/wp-content/uploads/2019/03/Screenshot-at-2019-03-02-1041.png?resize=434%2C140&amp;ssl=1" alt="Create a Custom System Tray Indicator For Your Tasks on Linux 13" title="Create a Custom System Tray Indicator For Your Tasks on Linux 14"></p><p>現在，讓我們解釋一下這個魔法的原理：</p><ul><li>前三行代碼僅僅用來指明 Python 的路徑並且導入需要的庫。</li><li><code>def main()</code> ：此為指示器的主函數。該函數的代碼用來初始化並創建指示器。</li><li><code>indicator = appindicator.Indicator.new(&quot;customtray&quot;，&quot;semi-starred-symbolic&quot;，appindicator.IndicatorCategory.APPLICATION_STATUS)</code> ：這裏我們指明創建一個名為 <code>customtray</code> 的新指示器。這是指示器的唯一名稱，這樣系統就不會與其他運行中的指示器搞混了。同時我們使用名為 <code>semi-starred-symbolic</code> 的圖標作為指示器的默認圖標。你可以將之改成任何其他值；比如 <code>firefox</code> (如果你希望該指示器使用 FireFox 的圖標)，或任何其他你想用的圖標名。最後與 <code>APPLICATION_STATUS</code> 相關的部分是指明指示器類別/範圍的常規代碼。</li><li><code>indicator.set_status(appindicator.IndicatorStatus.ACTIVE)</code>：這一行激活指示器。</li><li><code>indicator.set_menu(menu())</code>：這裏説的是我們想使用 <code>menu()</code> 函數（我們會在後面定義) 來為我們的指示器創建菜單項。這很重要，可以讓你右擊指示器後看到一個可以實施行為的列表。</li><li><code>gtk.main()</code>：運行 GTK 主循環。</li><li>在 <code>menu()</code> 中我們定義了想要指示器提供的行為或項目。<code>command_one = gtk.MenuItem(&#39;My Notes&#39;)</code> 僅僅使用文本 “My notes” 來初始化第一個菜單項，接下來 <code>command_one.connect(&#39;activate&#39;，note)</code> 將菜單的 <code>activate</code> 信號與後面定義的 <code>note()</code> 函數相連接；換句話説，我們告訴我們的系統：“當該菜單項被點擊，運行 <code>note()</code> 函數”。最後，<code>menu.append(command_one)</code> 將菜單項添加到列表中。</li><li><code>exittray</code> 相關的行是為了創建一個退出的菜單項，以便讓你在想要的時候關閉指示器。</li><li><code>menu.show_all()</code> 以及 <code>return menu</code> 只是返回菜單項給指示器的常規代碼。</li><li>在 <code>note(_)</code> 下面是點擊 “My Notes” 菜單項時需要執行的代碼。這裏只是 <code>os.system(&quot;gedit $HOME/Documents/notes.txt&quot;)</code> 這一句話；<code>os.system</code> 函數允許你在 Python 中運行 shell 命令，因此這裏我們寫了一行命令來使用 <code>gedit</code> 打開家目錄下 <code>Documents</code> 目錄中名為 <code>notes.txt</code> 的文件。例如，這個可以稱為你今後的日常筆記程序了！</li></ul><h3 id="添加你所需要的任務" tabindex="-1">添加你所需要的任務 <a class="header-anchor" href="#添加你所需要的任務" aria-label="Permalink to “添加你所需要的任務”">​</a></h3><p>你只需要修改代碼中的兩塊地方：</p><ol><li>在 <code>menu()</code> 中為你想要的任務定義新的菜單項。</li><li>創建一個新的函數讓給該菜單項被點擊時執行特定的行為。</li></ol><p>所以，比如説你想要創建一個新菜單項，在點擊後，會使用 VLC 播放硬盤中某個特定的視頻/音頻文件？要做到這一點，只需要在第 17 行處添加下面三行內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command_two = gtk.MenuItem(&#39;Play video/audio&#39;)</span></span>
<span class="line"><span>command_two.connect(&#39;activate&#39;, play)</span></span>
<span class="line"><span>menu.append(command_two)</span></span></code></pre></div><p>然後在第 30 行添加下面內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def play(_):</span></span>
<span class="line"><span>  os.system(&quot;vlc /home/&lt;username&gt;/Videos/somevideo.mp4&quot;)</span></span></code></pre></div><p>將 <code>/home/&lt;username&gt;/Videos/somevideo.mp4</code> 替換成你想要播放的視頻/音頻文件路徑。現在保存該文件然後再次運行該指示器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python tray.py</span></span></code></pre></div><p>你將會看到：</p><p><img src="https://i2.wp.com/fosspost.org/wp-content/uploads/2019/03/Screenshot-at-2019-03-02-1141.png?resize=440%2C149&amp;ssl=1" alt="Create a Custom System Tray Indicator For Your Tasks on Linux 15" title="Create a Custom System Tray Indicator For Your Tasks on Linux 16"></p><p>而且當你點擊新創建的菜單項時，VLC 會開始播放！</p><p>要創建其他項目/任務，只需要重複上面步驟即可。但是要小心，需要用其他命令來替換 <code>command_two</code>，比如 <code>command_three</code>，這樣在變量之間才不會產生衝突。然後定義新函數，就像 <code>play(_)</code> 函數那樣。</p><p>可能性是無窮的；比如我用這種方法來從網上獲取數據（使用 urllib2 庫）並顯示出來。我也用它來在後台使用 <code>mpg123</code> 命令播放 mp3 文件，而且我還定義了另一個菜單項來 <code>killall mpg123</code> 以隨時停止播放音頻。比如 Steam 上的 CS:GO 退出很費時間（窗口並不會自動關閉），因此，作為一個變通的方法，我只是最小化窗口然後點擊某個自建的菜單項，它會執行 <code>killall -9 csgo_linux64</code> 命令。</p><p>你可以使用這個指示器來做任何事情：升級系統包、運行其他腳本——字面上的任何事情。</p><h3 id="自動啓動" tabindex="-1">自動啓動 <a class="header-anchor" href="#自動啓動" aria-label="Permalink to “自動啓動”">​</a></h3><p>我們希望系統托盤指示器能在系統啓動後自動啓動，而不用每次都手工運行。要做到這一點，只需要在自啓動應用程序中添加下面命令即可（但是你需要將 <code>tray.py</code> 的路徑替換成你自己的路徑）:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nohup python /home/&lt;username&gt;/tray.py &amp;</span></span></code></pre></div><p>下次重啓系統，指示器會在系統啓動後自動開始工作了！</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>你現在知道了如何為你想要的任務創建自己的系統托盤指示器了。根據每天需要運行的任務的性質和數量，此方法可以節省大量時間。有些人偏愛從命令列創建別名，但是這需要你每次都打開終端窗口或者需要有一個可用的下拉式終端仿真器，而這裏，這個系統托盤指示器一直在工作，隨時可用。</p><p>你以前用過這個方法來運行你的任務嗎？很想聽聽你的想法。</p><hr>`,32)),i("p",null,[s[4]||(s[4]=a("via: ",-1)),e(n,{href:"https://fosspost.org/tutorials/custom-system-tray-icon-indicator-linux"},{default:t(()=>[...s[3]||(s[3]=[a("https://fosspost.org/tutorials/custom-system-tray-icon-indicator-linux",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=a("作者：",-1)),e(n,{href:"https://fosspost.org/author/mhsabbagh"},{default:t(()=>[...s[5]||(s[5]=[a("M.Hanny Sabbagh",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[7]||(s[7]=[a("lujun9972",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const x=p(c,[["render",u]]);export{C as __pageData,x as default};
